COMMON='''Create one high-fidelity, beautifully art-directed Chinese PRODUCT UI concept for “算力共享” / “Token Share Mesh”, a genuine C2C marketplace where INDIVIDUAL sellers list idle personal computing devices. It is a design concept with demo data.
Hard framing: one flat straight-on edge-to-edge page, no physical device frame, no phone mockup, no hand/desk, no perspective, no multi-screen collage, no palette/style labels, no captions outside UI, no watermarks. Draw actual legible UI, not a presentation board.
EXACT shared resource data: “RTX 4090 · 24GB”; seller “星河同学”; “个人卖家”; service “ComfyUI · 图像生成”; “¥0.60 / 张”. Secondary PHONE MUST explicitly be “摩托罗拉 X30”; model “Qwen 3B”; seller “阿澄”; “¥0.02 / 千Token”. The phone's visible TITLE MUST be the concrete model 摩托罗拉 X30, not a generic operating-system label. NEVER print “Android设备”, “Android 设备”, “Android设别”, “手机推理” as its name. Do not invent version fields, CUDA versions, benchmarks, ratings, sales, guarantee badges, or income claims.
Service modes exactly “明文 / 端对端加密 / 显卡租赁”; select “端对端加密”. Categories “全部 / 对话 / 图像 / 视频”; select 全部. Main resource privacy text: “平台不可见”. Details/Web must also state “平台不可见；执行设备仍需处理明文”. Do not claim the hardware owner cannot access plaintext.
Consistent brand glyph: a minimal mesh of three connected nodes, drawn in this family's style; repeat the same glyph across its pages.
Text must be correct concise Simplified Chinese, clear touch targets and coherent hierarchy. Dark enough text and well-separated control edges. Never hide a resource's model/price behind the bottom bar. The two mobile pages must look like Alipay MINI-PROGRAM pages with a small top status bar, proper Alipay capsule in top-right, and safe-area insets.
Each family is an independent DESIGN LANGUAGE AND LAYOUT. Do not revert to the generic search + pills + two identical rounded picture-left marketplace cards. All properties below are deliberate constraints, not loose inspiration.
'''

PAGE_COMMON={
    'home':'''TARGET: ONE BUYER MARKET HOME, portrait 1024x1536. Show two complete visible resources with the exact shared data, primary 查看服务 action and clear privacy selection. Include useful search with placeholder 搜索模型、设备或卖家. Bottom has 发现 / 订单 / 共享 / 我的, 发现 selected. Category controls may use the family's prescribed position. Balance the complete page with no unnecessary marketing paragraphs or duplicate giant headings.''',
    'detail':'''TARGET: ONE SERVICE DETAIL, portrait 1024x1536, for the exact GPU offer in the reference. Top back arrow and 服务详情, Alipay capsule/status treatment matches home. Show RTX 4090 · 24GB, 星河同学 / 个人卖家, ComfyUI · 图像生成, small capability labels SDXL 1.0 / 24GB显存 / 按张计费. Include the three privacy modes with 端对端加密 selected and the readable boundary sentence 平台不可见；执行设备仍需处理明文. Fee preview exactly 卖家服务 ¥0.57, 平台服务费 ¥0.03, 合计 ¥0.60. Budget 预算上限 ¥5.00. State 本地网关未连接. Fixed bottom has total ¥0.60 / 张 and primary 连接网关并继续. No bottom tab navigation, no paid-success screen, no immediate payment CTA. Fit everything with legible text. The phone need not appear on this GPU detail.''',
    'web':'''TARGET: ONE DESKTOP WEB COMPUTE MARKET WORKSPACE, landscape 1536x1024. This is the same family's desktop companion, not a phone pasted onto desktop. Navigation offers 工作台 / 算力市场 / 我的订单 / 本地网关 / API密钥 / 账单, 算力市场 selected, located exactly as the family layout specifies. Page title 算力工作台. Include search and the same modes/categories, same GPU and concrete 摩托罗拉 X30 phone listing. Selected GPU contract/quote summary must contain seller 星河同学, mode 端对端加密, readable sentence 平台不可见；执行设备仍需处理明文, 预算上限 ¥5.00, exact fee rows 卖家服务 ¥0.57 / 平台服务费 ¥0.03 / 合计 ¥0.60, state 本地网关未连接, primary 连接网关 and secondary 查看合同. No charts, no fake analytics or sales, no code blocks, no platform-owned fleet. It must read as a usable buyer marketplace/connection workspace.'''
}

def main():
    jobs=[]
    for style in STYLES:
        folder=BASE/(style['id']+'-'+style['name'])
        prompts=folder/'prompts';prompts.mkdir(parents=True,exist_ok=True)
        (folder/'design-system.json').write_text(json.dumps(style,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        for page,filename,size in [('home','01-小程序-首页.png','1024x1536'),('detail','02-小程序-服务详情.png','1024x1536'),('web','03-Web-算力工作台.png','1536x1024')]:
            prompt=COMMON+'\nDESIGN FAMILY: '+style['kind']+'\nMATERIAL AND SHAPE GRAMMAR:\n'+style['material']+'\nTYPE:\n'+style['type']+'\nPALETTE ROLES (do not print codes): '+json.dumps(style['colors'])+'\n\n'
            if page!='home':
                prompt+='REFERENCE RULE: the attached image is THIS family’s approved home anchor. Preserve its observed brand glyph, type, material, color roles, icon treatment, component geometry and selected states. Use the NEW target layout below, not the home content. Never paste the source screenshot into the result. The final image contains ONLY the new target page.\n\n'
            prompt+=PAGE_COMMON[page]+'\n\nREQUIRED UNIQUE PAGE COMPOSITION:\n'+style[page]+'\n\nBefore finishing, verify the device names, units, selected privacy, one-page framing and the family-specific material. A color swap of a generic UI is not acceptable. Make this a resolved professional design.'
            path=prompts/(page+'.txt');path.write_text(prompt,encoding='utf-8')
            jobs.append(dict(id=style['id']+'-'+page,style=style['id'],style_name=style['name'],page=page,model='gpt-image-2.5',quality='high',size=size,output=str((folder/filename).relative_to(BASE)),prompt=str(path.relative_to(BASE)),reference=None if page=='home' else str((folder/'01-小程序-首页.png').relative_to(BASE))))
    (BASE/'production/jobs.json').write_text(json.dumps(dict(revision='V2',model='gpt-image-2.5',jobs=jobs),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    data=BASE/'production/skills/ui-ux-pro-max/data/styles.csv'
    with data.open(encoding='utf-8-sig',newline='') as f:
        rows=list(csv.DictReader(f))
    selected=[]
    for style in STYLES:
        matches=[r for r in rows if r.get('Style ID')==style['style_id']]
        if len(matches)!=1:raise RuntimeError('Expected one verified style record: '+style['style_id'])
        selected.append(dict(family=style['id'],query=style['kind'],verified_match=matches[0]))
    (BASE/'production/research/verified-style-records.json').write_text(json.dumps(selected,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(families=5,images=15,concrete_phone='摩托罗拉 X30',verified_style_records=len(selected)),ensure_ascii=False))

if __name__=='__main__':main()
